solution:
function resumerPlaces(fiches) {
  let total = 0;
  for (const fiche of fiches) { total = total + fiche.places; }
  const nombre = fiches.length;
  if (nombre === 0) { return { total:0, nombre:0, moyenne:null }; }
  return { total:total, nombre:nombre, moyenne:total / nombre };
}

